fixture_files.test_retry.py:
import unittest
from policy import total_attempts
from runner import run_with_retry

class RetryTests(unittest.TestCase):
    def test_retries_false_then_succeeds(self):
        outcomes = iter([False, True])
        self.assertTrue(run_with_retry(lambda: next(outcomes), retries=1))

    def test_retries_runtime_error_then_succeeds(self):
        calls = 0
        def operation():
            nonlocal calls
            calls += 1
            if calls == 1:
                raise RuntimeError("temporary")
            return True
        self.assertTrue(run_with_retry(operation, retries=1))
        self.assertEqual(calls, 2)

    def test_zero_retries_still_attempts_once(self):
        self.assertEqual(total_attempts(0), 1)
        self.assertTrue(run_with_retry(lambda: True, retries=0))

